#!/usr/bin/env bash
set -eu
ref=${PROBE_REF:-HEAD}
config=$(git show "$ref:apps/web/playwright.mocked.config.ts") || { echo 'not yet: config unreadable'; exit 75; }
rules=$(git show "$ref:infra/platform/documents/builder-rules.md") || { echo 'not yet: rules unreadable'; exit 75; }
pin=$(git show "$ref:apps/web/scripts/a-direct-mocked-run-refuses-a-foreign-server.test.ts") || { echo 'not yet: ownership matrix unreadable'; exit 75; }
case "$config" in *'reuseExistingServer: false,'*) ;; *) echo 'not yet: direct refusal absent'; exit 75;; esac
case "$rules" in *'Focused mocked browser runs use'*) ;; *) echo 'not yet: focused runner door absent'; exit 75;; esac
case "$pin" in *"for (const mode of ['local', 'forge-ci'] as const)"*) ;; *) echo 'not yet: local and Forge CI ownership matrix absent'; exit 75;; esac
case "$pin" in *"GITHUB_ACTIONS: mode === 'forge-ci'"*) ;; *) echo 'not yet: GitHub Actions marker coverage absent'; exit 75;; esac
case "$pin" in *"FORGEJO_ACTIONS: mode === 'forge-ci'"*"expect(safe.output).toContain(mode === 'forge-ci'"*) ;; *) echo 'not yet: CI markers or exact path assertion absent'; exit 75;; esac
echo 'direct mocked refusal and local Forge CI ownership matrix source present'
